CREATE TABLE IF NOT EXISTS schema_migrations(version int PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY, username text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','viewer')));
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), revoked boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tokens(hash text PRIMARY KEY, session_id uuid NOT NULL REFERENCES sessions(id), kind text NOT NULL, used boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id text PRIMARY KEY, status text NOT NULL DEFAULT 'idle' CHECK(status IN ('idle','online','rate_limited','disconnected','suspended','session_expired')), platform_user_id text UNIQUE, rate_limited_until timestamptz, version int NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS groups(id uuid PRIMARY KEY, gateway_group_id text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'active', creator_account_id text NOT NULL REFERENCES accounts(id), agent_enabled boolean NOT NULL DEFAULT false, auto_kick_enabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS group_members(group_id uuid NOT NULL REFERENCES groups(id), platform_user_id text NOT NULL, account_id text REFERENCES accounts(id), role text NOT NULL DEFAULT 'member', PRIMARY KEY(group_id,platform_user_id));
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY, kind text NOT NULL, group_id uuid REFERENCES groups(id), status text NOT NULL DEFAULT 'running', data jsonb NOT NULL, progress jsonb NOT NULL DEFAULT '{}', errors jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY, group_id uuid NOT NULL REFERENCES groups(id), client_msg_id uuid UNIQUE, msg_id text, account_id text REFERENCES accounts(id), sender_platform_user_id text, is_own boolean NOT NULL, text text NOT NULL, sent_at timestamptz NOT NULL DEFAULT now(), received_at timestamptz NOT NULL DEFAULT now(), delivery_status text, fail_code text, source text, source_id uuid, attempt_count int NOT NULL DEFAULT 0, attempt_started_at timestamptz, unknown_since timestamptz, attempted boolean NOT NULL DEFAULT false, UNIQUE(group_id,msg_id));
CREATE TABLE IF NOT EXISTS gateway_inbox(event_id bigint PRIMARY KEY, type text NOT NULL, data jsonb NOT NULL, processed boolean NOT NULL DEFAULT false, received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS event_counter(id int PRIMARY KEY, value bigint NOT NULL DEFAULT 0);
INSERT INTO event_counter(id) VALUES(1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS realtime_events(seq bigint PRIMARY KEY, type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_runs(id uuid PRIMARY KEY, group_id uuid NOT NULL REFERENCES groups(id), status text NOT NULL DEFAULT 'running', end_reason text, summary text, history jsonb NOT NULL, step_count int NOT NULL DEFAULT 0, protocol_errors int NOT NULL DEFAULT 0, elapsed_ms bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_agent_per_group ON agent_runs(group_id) WHERE status='running';
CREATE TABLE IF NOT EXISTS agent_pending_messages(message_id uuid PRIMARY KEY REFERENCES messages(id), group_id uuid NOT NULL REFERENCES groups(id));
CREATE TABLE IF NOT EXISTS agent_steps(id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES agent_runs(id), step_index int NOT NULL, kind text NOT NULL, tool_use_id text, name text, input jsonb, result_summary text, result jsonb, is_error boolean NOT NULL DEFAULT false, error_code text, audit_verdict text, audit_attempts int NOT NULL DEFAULT 0, raw_response text, phase text NOT NULL DEFAULT 'received', UNIQUE(run_id,step_index));
CREATE TABLE IF NOT EXISTS agent_send_keys(run_id uuid NOT NULL REFERENCES agent_runs(id), key text NOT NULL, message_id uuid NOT NULL REFERENCES messages(id), PRIMARY KEY(run_id,key));
CREATE TABLE IF NOT EXISTS sequences(id uuid PRIMARY KEY, name text NOT NULL, steps jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS sequence_runs(id uuid PRIMARY KEY, group_id uuid NOT NULL REFERENCES groups(id), sequence_id uuid NOT NULL REFERENCES sequences(id), status text NOT NULL DEFAULT 'running', current_step_index int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_sequence_per_group ON sequence_runs(group_id) WHERE status='running';
CREATE TABLE IF NOT EXISTS sequence_run_steps(run_id uuid NOT NULL REFERENCES sequence_runs(id), index int NOT NULL, status text NOT NULL DEFAULT 'pending', account_role text NOT NULL, text text NOT NULL, delay_seconds numeric NOT NULL, scheduled_at timestamptz, sent_at timestamptz, client_msg_id uuid REFERENCES messages(client_msg_id), resolved_vars jsonb NOT NULL, var_sources jsonb NOT NULL, PRIMARY KEY(run_id,index));
CREATE TABLE IF NOT EXISTS timeline_snapshots(id uuid PRIMARY KEY, group_id uuid NOT NULL REFERENCES groups(id), message_ids uuid[] NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '1 hour');
CREATE TABLE IF NOT EXISTS pending_disconnects(account_id text PRIMARY KEY REFERENCES accounts(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS message_timeline ON messages(group_id,sent_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS message_queue ON messages(account_id,received_at,id) WHERE delivery_status IN ('queued','unknown','accepted');
CREATE INDEX IF NOT EXISTS pending_inbox ON gateway_inbox(event_id) WHERE processed=false;
-- Demo services use separate tables and communicate with the app only through HTTP/SSE.
CREATE TABLE IF NOT EXISTS mock_state(key text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS mock_events(id bigserial PRIMARY KEY, type text NOT NULL, data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS mock_tasks(id uuid PRIMARY KEY, due_at timestamptz NOT NULL, kind text NOT NULL, data jsonb NOT NULL);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
